public boolean validateStructure()
{
    UPSPricingAttributeGroup pricingAttributeGroup;
    UPSPricingAttributeLink pricingAttributeLink;
    Set unionSet;
    boolean isValid = true;
    Set recordSet = this.getAttributeLinkRecordSet();
    int numberOfLink = recordSet.elements();
    SetEnumerator setEnum = recordSet.getEnumerator();

    if (!setEnum.moveNext())
    {
        warning("@UnifiedPricingService:UPSPricingAttributeGroup_EmptyPricingAttributeGroup");
        isValid = false;
    }
    else
    {
        pricingAttributeLink = setEnum.current();
        unionSet = pricingAttributeLink.getAttributeGroupRecIdRecordSet();

        while (setEnum.moveNext())
        {
            pricingAttributeLink = setEnum.current();
            unionSet = Set::intersection(unionSet, pricingAttributeLink.getAttributeGroupRecIdRecordSet());
        }

        unionSet.remove(this.RecId);

        if (!unionSet.empty())
        {
            setEnum = unionSet.getEnumerator();

            while (setEnum.moveNext())
            {
                pricingAttributeGroup = UPSPricingAttributeGroup::find(setEnum.current());

                if (pricingAttributeGroup.getAttributeLinkRecordSet().elements() == numberOfLink)
                {
                    warning(strFmt("@UnifiedPricingService:UPSPricingAttributeGroup_DuplicateStructure", pricingAttributeGroup.Name));
                    isValid = false;
                    break;
                }
            }
        }
    }

    return isValid;
}

private Set getAttributeLinkRecordSet()
{
    UPSPricingAttributeLink pricingAttributeLink;
    Set recordSet = new Set(Types::Record);

    while select PriceAttributeClassId, AttributeProviderClassId, AttributeName, TypeName from pricingAttributeLink where pricingAttributeLink.PriceAttributeGroup == this.RecId
    {
        recordSet.add(pricingAttributeLink);
    }

    return recordSet;
}

public static UPSPricingAttributeGroup find(RecId _recId, boolean _update = false)
{
    UPSPricingAttributeGroup  pricingAttributeGroup;

    pricingAttributeGroup.selectForUpdate(_update);

    if (_recId)
    {
        select firstonly pricingAttributeGroup
            where pricingAttributeGroup.RecId == _recId;
    }

    return pricingAttributeGroup;
}

public static UPSPricingAttributeGroup findByName(Name _name, boolean _update = false)
{
    UPSPricingAttributeGroup  pricingAttributeGroup;

    pricingAttributeGroup.selectForUpdate(_update);

    select firstonly pricingAttributeGroup
        where pricingAttributeGroup.Name == _name;

    return pricingAttributeGroup;
}

internal boolean matchSource(UPSPricingAttributeSource _source)
{
    UPSPricingAttributeLink link;

    while select link where link.PriceAttributeGroup == this.RecId
    {
        if (UPSPricingAttributeRepository::getPricingSourceDetail(link.pricingAttribute()).source != _source)
        {
            return false;
        }
    }

    return true;
}

public static boolean isPricingAttributeGroupUsed(RecId _recId)
{
    boolean ret = false;

    if (_recId)
    {
        UPSPricingRule  upsPricingRule;

        select firstonly RecId from upsPricingRule
            where upsPricingRule.PriceAttributeGroup == _recId;

        ret = upsPricingRule.recid;

        if (!ret)
        {
            UPSPricingAttributeLink attributeLink;
            UPSPricingRuleCondition ruleCondition;
            UPSPricingAttributeGroup upsCustomerOrProductPriceGroup;

            select firstonly RecId from  attributeLink
                where attributeLink.PriceAttributeClassId == classNum(UPSPricingAttributeCustomerPriceGroup)
                    || attributeLink.PriceAttributeClassId == classNum(UPSPricingAttributeProductPriceGroup)
            join RecId from ruleCondition
                where ruleCondition.ConditionAttribute == attributeLink.RecId
            join RecId from upsCustomerOrProductPriceGroup
                where (upsCustomerOrProductPriceGroup.GroupType == UPSPricingAttributeGroupType::Customer
                        || upsCustomerOrProductPriceGroup.GroupType == UPSPricingAttributeGroupType::Product)
                    && upsCustomerOrProductPriceGroup.Name == RuleCondition.ConditionValue
                    && upsCustomerOrProductPriceGroup.RecId == _recId;

            ret = attributeLink.recid;
        }
    }

    return ret;
}

/// <summary>
/// Include or exclude line related to current pricing rule
/// </summary>
/// <param name = "_lineType">Action to perform - include or exclude</param>
/// <param name = "_refTableId">Reference table Id of line to be included/excluded</param>
/// <param name = "_refRecId">Reference record Id of line to be included/excluded</param>
public void inclExclRelLine(UPSPricingAttributeLineType _lineType, RefTableId _refTableId, RefRecId _refRecId)
{
    if (_lineType == UPSPricingAttributeLineType::Exclude)
    {
        UPSPricingAttributeLineState::excludeLine(this.TableId, this.RecId, _refTableId, _refRecId);
    }
    else
    {
        UPSPricingAttributeLineState::includeLine(this.TableId, this.RecId, _refTableId, _refRecId);
    }
}
